<?php
use DigiForge\Queue\ScheduledTaskReadModel;
require_once __DIR__.'/fixtures/PortalAccessFixture.php';
final class SchedulerMetadata17Test extends WP_UnitTestCase {
 private function read(mixed $hook,mixed $args):array {$a=new class($hook,$args){public function __construct(private mixed $h,private mixed $a){}public function get_hook(){return $this->h;}public function get_args(){return $this->a;}};return (new ScheduledTaskReadModel(static fn()=>[['id'=>7,'state'=>'PENDING','action'=>$a]],static fn()=>[]))->snapshot();}
 public function testDocumentedLegacyDispatcherIsReadWithoutRunningOrWriting():void {
  $s=$this->read('digiforge_u3_build_product',[9,'digital']);self::assertSame('AVAILABLE',$s['query_state']['action_scheduler']);self::assertSame(hash('sha256','u3-auto-candidate-9-digital'),$s['items'][0]['run_key_sha256']);self::assertSame('LEGACY_DEFAULT',$s['items'][0]['run_key_source']);self::assertSame('dispatcher',$s['items'][0]['stage']);self::assertSame('DISPATCH_V1',$s['items'][0]['metadata_format']);self::assertFalse($s['external_execution_authorized']);self::assertFalse($s['retry_permitted']);self::assertTrue($s['read_only']);
 }
 public function testDocumentedStageDefaultAndCurrentFormats():void {foreach([['digiforge_u3_build_product_stage',[9,'goods','private-run'],'develop','STAGE_V1'],['digiforge_u3_build_product_stage',[9,'goods','private-run','manifest_poll'],'manifest_poll','STAGE_V2'],['digiforge_u3_build_product',[9,'goods','private-run'],'dispatcher','DISPATCH_V2'],['digiforge_u3_build_product',[9,'goods',''],'dispatcher','DISPATCH_V2']]as [$hook,$args,$stage,$format]){$s=$this->read($hook,$args);self::assertSame('AVAILABLE',$s['query_state']['action_scheduler']);self::assertSame($stage,$s['items'][0]['stage']);self::assertSame($format,$s['items'][0]['metadata_format']);self::assertStringNotContainsString('private-run',wp_json_encode($s));}}
 public function testFieldFailuresRemainBoundedAndDenyUnauthorizedCombinations():void {
  $cases=[['unknown',[9,'digital','private'],'HOOK_NOT_ALLOWED'],['digiforge_u3_build_product',null,'ARGUMENTS_NOT_ARRAY'],['digiforge_u3_build_product',[9],'ARGUMENT_COUNT'],['digiforge_u3_build_product',['9','digital','private'],'CANDIDATE_TYPE'],['digiforge_u3_build_product',[0,'digital','private'],'CANDIDATE_RANGE'],['digiforge_u3_build_product',[9,'personalized_pod','private'],'SHOP_NOT_ALLOWED'],['digiforge_u3_build_product',[9,'jewelry','private'],'SHOP_NOT_ALLOWED'],['digiforge_u3_build_product',[9,'digital',null],'RUN_KEY_INVALID'],['digiforge_u3_build_product',[9,'digital',str_repeat('x',192)],'RUN_KEY_INVALID'],['digiforge_u3_build_product_stage',[9,'goods',''],'RUN_KEY_INVALID'],['digiforge_u3_build_product_stage',[9,'goods','private','dispatcher'],'STAGE_NOT_ALLOWED'],['digiforge_u3_build_product_stage',[9,'goods','private','publish'],'STAGE_NOT_ALLOWED'],['digiforge_u3_build_product',[9,'goods','private','finalize'],'ARGUMENT_COUNT']];
  foreach($cases as [$hook,$args,$reason]){$s=$this->read($hook,$args);self::assertSame('UNAVAILABLE',$s['query_state']['action_scheduler']);self::assertSame('TASK_METADATA',$s['action_scheduler_query']['subreason_code']);self::assertSame($reason,$s['action_scheduler_query']['metadata_reason_code']);self::assertSame([],$s['items']);self::assertStringNotContainsString('private',wp_json_encode($s));self::assertFalse($s['external_execution_authorized']);}
 }
 public function testLegacyCronMetadataUsesSameReadOnlyContract():void {$s=(new ScheduledTaskReadModel(static fn()=>[],static fn()=>[1700000000=>['digiforge_u3_build_product'=>[['args'=>[9,'digital']]]]]))->snapshot();self::assertSame('AVAILABLE',$s['query_state']['wp_cron']);self::assertSame('DISPATCH_V1',$s['items'][0]['metadata_format']);}
 public function testRenderedAutomationIncludesBoundedMetadataReason():void {PortalAccessFixture::reset();PortalAccessFixture::enroll();$_GET=['df_view'=>'automation','df_shop'=>'all'];$m=new ReflectionMethod(DigiForge\Portal\Portal::class,'automationOperations');$m->setAccessible(true);ob_start();$m->invoke(new DigiForge\Portal\Portal());$h=ob_get_clean();self::assertStringContainsString('Task metadata reason',$h);$h=(new DigiForge\Portal\SchedulerDependencyPanel())->render(['action_scheduler_query'=>['metadata_reason_code'=>'private<script>']]);self::assertStringContainsString('UNVERIFIED',$h);self::assertStringNotContainsString('private',$h);self::assertStringNotContainsString('<script>',$h);$_GET=[];global $wpdb;$wpdb->query('COMMIT');PortalAccessFixture::reset();$wpdb->query('COMMIT');$wpdb->query('START TRANSACTION');}
}
